import openapiTS, { astToString } from 'openapi-typescript';
import prettier from 'prettier';
import { buildOpenApiDocument } from '../openapi';

const HEADER =
  '// GENERATED by `pnpm --filter @easyfi/contracts gen:client` from the zod contracts. Do not edit.\n';

/** OpenAPI document → TypeScript `paths`/`components` types, formatted with the repo prettier config. */
export async function generateClientTypes(): Promise<string> {
  const doc = buildOpenApiDocument();
  const ast = await openapiTS(doc as unknown as Parameters<typeof openapiTS>[0]);
  const config = (await prettier.resolveConfig(new URL('./schema.gen.ts', import.meta.url))) ?? {};
  return prettier.format(HEADER + astToString(ast), { ...config, parser: 'typescript' });
}
